package net.civeira.phylax.feature.observe.observedslo.application.usecase.create;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSloChangeSet;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSloKindOptions;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedSloCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed slo input values are kept when converted to a change set and back")
  void test_observed_slo_create_input_change_set_round_trip() {
    ObservedSloCreateInput input = ObservedSloCreateInput.builder().uid("one").name("one")
        .origin(ObservedSourceReference.of("one")).route("one")
        .kind(ObservedSloKindOptions.AVAILABILITY).objective(1).latencyMs(1).windowDays(1)
        .enabled(true).version(1).build();
    ObservedSloChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    ObservedSloCreateInput copy = ObservedSloCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getName().isPresent(), "name must be assigned by the builder");
    Assertions.assertEquals(input.getName(), copy.getName(),
        "name must survive the change set round trip");
    Assertions.assertTrue(input.getOrigin().isPresent(), "origin must be assigned by the builder");
    Assertions.assertEquals(input.getOrigin(), copy.getOrigin(),
        "origin must survive the change set round trip");
    Assertions.assertTrue(input.getRoute().isPresent(), "route must be assigned by the builder");
    Assertions.assertEquals(input.getRoute(), copy.getRoute(),
        "route must survive the change set round trip");
    Assertions.assertTrue(input.getKind().isPresent(), "kind must be assigned by the builder");
    Assertions.assertEquals(input.getKind(), copy.getKind(),
        "kind must survive the change set round trip");
    Assertions.assertTrue(input.getObjective().isPresent(),
        "objective must be assigned by the builder");
    Assertions.assertEquals(input.getObjective(), copy.getObjective(),
        "objective must survive the change set round trip");
    Assertions.assertTrue(input.getLatencyMs().isPresent(),
        "latencyMs must be assigned by the builder");
    Assertions.assertEquals(input.getLatencyMs(), copy.getLatencyMs(),
        "latencyMs must survive the change set round trip");
    Assertions.assertTrue(input.getWindowDays().isPresent(),
        "windowDays must be assigned by the builder");
    Assertions.assertEquals(input.getWindowDays(), copy.getWindowDays(),
        "windowDays must survive the change set round trip");
    Assertions.assertTrue(input.getEnabled().isPresent(),
        "enabled must be assigned by the builder");
    Assertions.assertEquals(input.getEnabled(), copy.getEnabled(),
        "enabled must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed slo input builder can generate a new identifier")
  void test_observed_slo_create_input_new_uid() {
    ObservedSloCreateInput input = ObservedSloCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(),
        ObservedSloCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the observed slo input starts empty and the setters assign values")
  void test_observed_slo_create_input_setters() {
    ObservedSloCreateInput empty = ObservedSloCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getName().isEmpty(), "name must be empty by default");
    Assertions.assertSame(empty, empty.setName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getName().isPresent(), "name must be assigned by the setter");
    Assertions.assertTrue(empty.getOrigin().isEmpty(), "origin must be empty by default");
    Assertions.assertSame(empty, empty.setOrigin(ObservedSourceReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getOrigin().isPresent(), "origin must be assigned by the setter");
    Assertions.assertTrue(empty.getRoute().isEmpty(), "route must be empty by default");
    Assertions.assertSame(empty, empty.setRoute("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getRoute().isPresent(), "route must be assigned by the setter");
    Assertions.assertTrue(empty.getKind().isEmpty(), "kind must be empty by default");
    Assertions.assertSame(empty, empty.setKind(ObservedSloKindOptions.AVAILABILITY),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getKind().isPresent(), "kind must be assigned by the setter");
    Assertions.assertTrue(empty.getObjective().isEmpty(), "objective must be empty by default");
    Assertions.assertSame(empty, empty.setObjective(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getObjective().isPresent(),
        "objective must be assigned by the setter");
    Assertions.assertTrue(empty.getLatencyMs().isEmpty(), "latencyMs must be empty by default");
    Assertions.assertSame(empty, empty.setLatencyMs(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getLatencyMs().isPresent(),
        "latencyMs must be assigned by the setter");
    Assertions.assertTrue(empty.getWindowDays().isEmpty(), "windowDays must be empty by default");
    Assertions.assertSame(empty, empty.setWindowDays(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getWindowDays().isPresent(),
        "windowDays must be assigned by the setter");
    Assertions.assertTrue(empty.getEnabled().isEmpty(), "enabled must be empty by default");
    Assertions.assertSame(empty, empty.setEnabled(true), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getEnabled().isPresent(), "enabled must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
